#include <bits/stdc++.h>
using namespace std;
class Solution {public:int numberOfWays(string s,string t,long long k){const long long MOD=1000000007;int n=s.size();string joined=t+'#'+s+s.substr(0,n-1);vector<int> pi(joined.size());for(int i=1;i<(int)joined.size();++i){int j=pi[i-1];while(j&&joined[i]!=joined[j])j=pi[j-1];if(joined[i]==joined[j])++j;pi[i]=j;}long long matches=0;for(int i=n+1;i<(int)joined.size();++i)if(pi[i]==n)++matches;long long a=(s==t),b=1-a;long long M[2][2]={{(matches-1+MOD)%MOD,matches%MOD},{(n-matches)%MOD,(n-matches-1+MOD)%MOD}};long long R[2][2]={{1,0},{0,1}};while(k){if(k&1){long long z[2][2]={};for(int i=0;i<2;++i)for(int j=0;j<2;++j)for(int p=0;p<2;++p)z[i][j]=(z[i][j]+R[i][p]*M[p][j])%MOD;memcpy(R,z,sizeof(z));}long long z[2][2]={};for(int i=0;i<2;++i)for(int j=0;j<2;++j)for(int p=0;p<2;++p)z[i][j]=(z[i][j]+M[i][p]*M[p][j])%MOD;memcpy(M,z,sizeof(z));k>>=1;}return (int)((R[0][0]*a+R[0][1]*b)%MOD);}};
